export function TicketCards({tickets}:{tickets:readonly Ticket[]}){return <ul>{tickets.map(ticket=><li key={ticket.id}><article><h3>#{ticket.id} {ticket.title}</h3><p>{ticket.status}</p></article></li>)}</ul>;}

